import manifest from "./gallery-manifest.json"

// Media files are generated by scripts/build-gallery-media.mjs; this file holds the words.
// Keep every claim here traceable to the event's written report.

export type GalleryImage = {
  type: "image"
  src: string
  thumb: string
  width: number
  height: number
  featured: boolean
  source: string
  alt: string
}

export type GalleryVideo = {
  type: "video"
  src: string
  poster: string
  width: number
  height: number
  duration: number
  featured: boolean
  source: string
  alt: string
}

export type GalleryMedia = GalleryImage | GalleryVideo

export type GalleryEvent = {
  slug: string
  name: string
  kind: string
  dateLabel: string
  isoDate: string
  place: string
  partner?: string
  /** A community HealthMind ran activity in (a summit audience is not one). */
  community?: string
  /** Attendance as given in the event report. */
  attendance?: { count: number; approximate: boolean; note: string }
  highlight: string
  summary: string[]
  /** Card accent, matching the event's own look. */
  accent: { from: string; via: string; to: string }
  media: GalleryMedia[]
}

type RawMedia = Omit<GalleryImage, "alt"> | Omit<GalleryVideo, "alt">

