function withAlt(slug: string, eventName: string, items: RawMedia[]): GalleryMedia[] {
  let photo = 0
  let video = 0
  return items.map((item) => {
    const index = item.type === "image" ? ++photo : ++video
    const fallback = `${eventName}: ${item.type === "image" ? "photo" : "video"} ${index}`
    return { ...item, alt: altText[slug]?.[item.source] ?? fallback } as GalleryMedia
  })
}

const rawEvents = manifest.events as Record<string, RawMedia[]>

export const galleryEvents: GalleryEvent[] = eventDetails.map((event) => ({
  ...event,
  media: withAlt(event.slug, event.name, rawEvents[event.slug] ?? []),
}))

/** Community Reach figures, derived from the event records above. */
export function communityReach() {
  const counted = galleryEvents.filter((e) => e.attendance)
  const people = counted.reduce((sum, e) => sum + (e.attendance?.count ?? 0), 0)
  const uncounted = galleryEvents.filter((e) => !e.attendance).map((e) => e.name)
  return {
    outreachEvents: galleryEvents.length,
    partners: [...new Set(galleryEvents.flatMap((e) => (e.partner ? [e.partner] : [])))],
    communities: [...new Set(galleryEvents.flatMap((e) => (e.community ? [e.community] : [])))],
    people: people
      ? {
          value: `${counted.some((e) => e.attendance?.approximate) ? "~" : ""}${people.toLocaleString("en-GB")}`,
          note: `${counted.map((e) => e.name).join(", ")} attendance (estimate)${uncounted.length ? `. ${uncounted.join(", ")} not yet counted.` : "."}`,
        }
      : null,
  }
}

function find(slug: string, source: string) {
  return galleryEvents.find((e) => e.slug === slug)?.media.find((m) => m.source === source)
}

/** The floating pieces at the top of the gallery, in display order. */
export const floatingPicks: { media: GalleryMedia; heroSrc?: string; eventSlug: string }[] = [
  { slug: "billi-now-now-2026", source: "VID-1.mp4" },
  { slug: "billi-now-now-2026", source: "IMG-7.jpeg" },
  { slug: "billi-now-now-2026", source: "IMG-5.jpeg" },
  { slug: "billi-now-now-2026", source: "IMG-6.jpeg" },
].flatMap(({ slug, source }) => {
  const media = find(slug, source)
  if (!media) return []
  const hero = media.type === "video" ? manifest.hero.find((h) => h.poster === media.poster) : undefined
  return [{ media, heroSrc: hero?.src, eventSlug: slug }]
})
